INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle externen IT-Dienste immer cloudbasiert?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch externe Rechenzentren umfassen"}, {"text": "Ja", "correct": false, "because": "Cloud ist nur ein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil, wenn ich IT-Ressourcen extern nutze?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Bedarf an"}, {"text": "Lokale Speicherkapazität", "correct": false, "because": "Weniger relevant"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen externe IT-Dienste attraktiv?', 5, '[{"text": "Hohe Verfügbarkeit", "correct": true, "because": "Garantiert Zugriff"}, {"text": "Kosteneffizienz", "correct": true, "because": "Reduziert Investitionen"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Lokale Installation", "correct": false, "because": "Nicht Off-Premises"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Externe Dienste schützen vor lokalen Ausfällen. b) Sie sind immer günstiger als On-Premises.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Anbieter ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines externen IT-Dienstes?', 4, '[{"text": "Sicherheitsstandards", "correct": false, "because": "Schützen Daten"}, {"text": "Vertragsbedingungen", "correct": false, "because": "Regeln Nutzung"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Dienste"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob externe Dienste immer Internet benötigen?', 2, '[{"text": "Ja", "correct": true, "because": "Zugriff erfolgt meist online"}, {"text": "Nein", "correct": false, "because": "Internet meist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für externe IT-Ressourcen entscheidend?', 3, '[{"text": "Datenverschlüsselung", "correct": true, "because": "Schützt Vertraulichkeit"}, {"text": "Lokale Rechenleistung", "correct": false, "because": "Weniger relevant"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern externe IT-Dienste ab?', 5, '[{"text": "Zugriffskontrollen", "correct": true, "because": "Verhindern unbefugten Zugriff"}, {"text": "Regelmäßige Audits", "correct": true, "because": "Prüfen Sicherheitsstandards"}, {"text": "Hohe lokale Bandbreite", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "Manuelle Backups", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass externe Dienste immer weniger Kontrolle bieten. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Anbieter verwalten Infrastruktur"}, {"text": "Nein", "correct": false, "because": "Kontrolle ist eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung externer IT-Ressourcen?', 4, '[{"text": "Service-Level-Agreements", "correct": true, "because": "Definieren Verfügbarkeit"}, {"text": "Lokale Hardware", "correct": false, "because": "Nicht erforderlich"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Externe Dienste bieten Flexibilität. b) Sie eliminieren lokale IT.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature finde ich bei externen IT-Diensten entscheidend?', 4, '[{"text": "Automatische Skalierung", "correct": true, "because": "Passt sich Bedarf an"}, {"text": "Hohe lokale Speicherkapazität", "correct": false, "because": "Weniger relevant"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass externe Dienste immer öffentlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Private Clouds möglich"}, {"text": "Ja", "correct": false, "because": "Privatsphäre einstellbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für externe IT-Ressourcen?', 3, '[{"text": "Sicherheitsprotokolle", "correct": false, "because": "Schützen Daten"}, {"text": "Vertragsdetails", "correct": false, "because": "Regeln Nutzung"}, {"text": "Lokale Serverräume", "correct": true, "because": "Off-Premises extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind externe Dienste immer schneller als lokale?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Infrastruktur ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten externe IT-Dienste?', 4, '[{"text": "Wartungsfreiheit", "correct": true, "because": "Anbieter übernehmen Updates"}, {"text": "Globale Erreichbarkeit", "correct": true, "because": "Zugriff von überall"}, {"text": "Lokale Steuerung", "correct": false, "because": "Nicht Off-Premises"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob externe Dienste immer SaaS sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IaaS oder PaaS möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Modelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Migration zu externen Diensten wichtig?', 3, '[{"text": "Datenkompatibilität", "correct": true, "because": "Sichert reibungslosen Übergang"}, {"text": "Lokale Speichergröße", "correct": false, "because": "Weniger relevant"}, {"text": "Manuelle Sicherung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöhen externe Dienste die Datensicherheit?', 3, '[{"text": "Ja", "correct": true, "because": "Professionelle Sicherheitsmaßnahmen"}, {"text": "Nein", "correct": false, "because": "Sicherheit oft höher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu externen IT-Diensten?', 4, '[{"text": "Hosting einer Unternehmensanwendung", "correct": true, "because": "Skalierbar und zugänglich"}, {"text": "Lokale Datenbanktests", "correct": false, "because": "On-Premises geeignet"}, {"text": "Hardwarewartung", "correct": false, "because": "Nicht Off-Premises"}]');
